window.POETRY_REGISTER("v4-pairs-22-4-0.js",{"poems":[["后记","孙望","唐","唐诗",52803,"v4-poems-52.js",803],["高宗时瑶（胡楚宾，秋浦〖贵池〗人。善属文，高宗召为右史、兼崇贤直学士，预选与诸儒论禁中，撰《臣轨》等书千余篇。朝廷疑议表疏密使参处，以分宰相权，号北门学士。楚宾为文甚敏，必酒中下笔。高宗每命作时，常以金银杯𣂏酒饮之，文成輙赐焉。其英资豪颖，与李白伦，故当时谣曰：）（《全唐诗》八七八《胡楚宾谣》，以为与晚唐顾云、张乔、殷文圭等为同时人，文字有不同。〖2〗）","无名氏","唐","唐诗",53526,"v4-poems-53.js",526]],"pairs":[["兹编则集日人及新罗人之与唐土人士有交往酬唱者","各自成卷",0,"茲編則集日人及新羅人之與唐土人士有交往酬唱者","",0],["是此谣至早亦应为天宝间李白居秋浦后方可能出现","题误甚明",1,"是此謠至早亦應爲天寶間李白居秋浦後方可能出現","題誤甚明",0]]});
